 **********************/

static void create_feature_card(lv_obj_t *parent, const char *icon,
                                 const char *title, const char *desc,
                                 app_page_id_t target)
{
    lv_obj_t *card = ui_comp_create_card(parent);
    lv_obj_set_size(card, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(card, card_click_cb, LV_EVENT_CLICKED,
                        (void *)(uintptr_t)target);

    /* Icon */
    lv_obj_t *icon_lbl = lv_label_create(card);
    lv_label_set_text(icon_lbl, icon);
    lv_obj_set_style_text_font(icon_lbl, ui_theme_font_large(), 0);
    lv_obj_set_style_text_color(icon_lbl,
                                ui_theme_get_color(THEME_COLOR_PRIMARY), 0);

    /* Title */
    lv_obj_t *title_lbl = lv_label_create(card);
    lv_label_set_text(title_lbl, title);
    ui_theme_apply_title_style(title_lbl);

    /* Description */
    lv_obj_t *desc_lbl = lv_label_create(card);
    lv_label_set_text(desc_lbl, desc);
    lv_label_set_long_mode(desc_lbl, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(desc_lbl, LV_PCT(100));
    lv_obj_set_style_text_color(desc_lbl,
                                ui_theme_get_color(THEME_COLOR_TEXT_MUTED), 0);
    lv_obj_set_style_text_font(desc_lbl, ui_theme_font_small(), 0);
}

