    ui_comp_create_labeled_value(about_card, "LVGL Version",
                                 "v9.1.0");
    ui_comp_create_labeled_value(about_card, "Architecture",
                                 "Layered MVC Pattern");

    /* Back to home button at bottom */
    static const char *btn_labels[] = { "Back to Home" };
    static const app_page_id_t btn_targets[] = { PAGE_HOME };
    ui_comp_create_nav_buttons(content, btn_labels, btn_targets, 1);

    return container;
