static void nav_btn_event_cb(lv_event_t *e)
{
    app_page_id_t target = (app_page_id_t)(uintptr_t)lv_event_get_user_data(e);
    page_manager_request_nav(NAV_ACTION_PUSH, target);
}

static void back_btn_event_cb(lv_event_t *e)
{
    LV_UNUSED(e);
    page_manager_request_nav(NAV_ACTION_POP, 0);
}

/**********************
 *  GLOBAL FUNCTIONS
