lv_obj_t *ui_comp_create_header(lv_obj_t *parent, const char *title,
                                 bool show_back)
{
    /* Header container - spans full width at top */
    lv_obj_t *header = lv_obj_create(parent);
    lv_obj_set_size(header, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(header, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(header, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_all(header, 12, 0);
    lv_obj_set_style_bg_color(header,
                              ui_theme_get_color(THEME_COLOR_PRIMARY), 0);
    lv_obj_set_style_bg_opa(header, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(header, 0, 0);
    lv_obj_set_style_border_width(header, 0, 0);
    lv_obj_remove_flag(header, LV_OBJ_FLAG_SCROLLABLE);

    /* Back button */
    if (show_back) {
        lv_obj_t *back_btn = lv_button_create(header);
        lv_obj_set_size(back_btn, 36, 36);
        lv_obj_set_style_bg_color(back_btn,
            lv_color_white(), 0);
        lv_obj_set_style_bg_opa(back_btn, LV_OPA_20, 0);
        lv_obj_set_style_border_width(back_btn, 0, 0);
        lv_obj_set_style_radius(back_btn, 18, 0);

        lv_obj_t *back_label = lv_label_create(back_btn);
        lv_label_set_text(back_label, LV_SYMBOL_LEFT);
        lv_obj_set_style_text_color(back_label, lv_color_white(), 0);
        lv_obj_center(back_label);

        lv_obj_add_event_cb(back_btn, back_btn_event_cb,
                            LV_EVENT_CLICKED, NULL);
    }

    /* Title label */
    lv_obj_t *lbl = lv_label_create(header);
    lv_label_set_text(lbl, title);
    lv_obj_set_style_text_font(lbl, ui_theme_font_large(), 0);
    lv_obj_set_style_text_color(lbl, lv_color_white(), 0);
    lv_obj_set_flex_grow(lbl, 1);

    return header;
}

lv_obj_t *ui_comp_create_card(lv_obj_t *parent)
{
    lv_obj_t *card = lv_obj_create(parent);
    lv_obj_set_size(card, LV_PCT(100), LV_SIZE_CONTENT);
    ui_theme_apply_card_style(card);
    lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(card, 16, 0);
    lv_obj_set_style_pad_gap(card, 8, 0);
    lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);

    return card;
}

lv_obj_t *ui_comp_create_labeled_value(lv_obj_t *parent,
                                        const char *label,
                                        const char *value)
{
    lv_obj_t *row = lv_obj_create(parent);
    lv_obj_set_size(row, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_BETWEEN,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_bg_opa(row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(row, 0, 0);
    lv_obj_set_style_pad_all(row, 4, 0);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *lbl = lv_label_create(row);
    lv_label_set_text(lbl, label);
    ui_theme_apply_text_style(lbl);

    lv_obj_t *val = lv_label_create(row);
    lv_label_set_text(val, value);
    lv_obj_set_style_text_color(val,
                                ui_theme_get_color(THEME_COLOR_PRIMARY), 0);

    return val; /* Return value label for later updates */
}

void ui_comp_create_separator(lv_obj_t *parent)
{
    lv_obj_t *sep = lv_obj_create(parent);
    lv_obj_set_size(sep, LV_PCT(100), 1);
    lv_obj_set_style_bg_color(sep,
        ui_theme_get_color(THEME_COLOR_TEXT_MUTED), 0);
    lv_obj_set_style_bg_opa(sep, LV_OPA_30, 0);
    lv_obj_set_style_border_width(sep, 0, 0);
}

void ui_comp_create_nav_buttons(lv_obj_t *parent,
                                 const char *labels[],
                                 const app_page_id_t targets[],
                                 uint32_t count)
{
    lv_obj_t *btn_row = lv_obj_create(parent);
    lv_obj_set_size(btn_row, LV_PCT(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(btn_row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(btn_row, LV_FLEX_ALIGN_SPACE_EVENLY,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_bg_opa(btn_row, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(btn_row, 0, 0);
    lv_obj_set_style_pad_all(btn_row, 8, 0);
    lv_obj_remove_flag(btn_row, LV_OBJ_FLAG_SCROLLABLE);

    for (uint32_t i = 0; i < count; i++) {
        lv_obj_t *btn = lv_button_create(btn_row);
        lv_obj_set_size(btn, LV_PCT(28), 44);
        lv_obj_set_style_bg_color(btn,
            ui_theme_get_color(THEME_COLOR_PRIMARY), 0);
        lv_obj_set_style_radius(btn, 8, 0);

        lv_obj_t *btn_lbl = lv_label_create(btn);
        lv_label_set_text(btn_lbl, labels[i]);
        lv_obj_set_style_text_color(btn_lbl, lv_color_white(), 0);
        lv_obj_center(btn_lbl);

        lv_obj_add_event_cb(btn, nav_btn_event_cb, LV_EVENT_CLICKED,
                            (void *)(uintptr_t)targets[i]);
    }
}

