                 APP_LVGLDEMO_TAG, path, (unsigned int)waited_ms, errno);
          return false;
        }

      usleep(50 * 1000);
      waited_ms += 50;
    }

  syslog(LOG_INFO, "[%s] display device ready: %s wait=%u ms\n",
         APP_LVGLDEMO_TAG, path, (unsigned int)waited_ms);
  return true;
}

static void app_lvgldemo_log_result(const char *fb_path,
                                    const lv_nuttx_result_t *result)
{
  lv_display_t *disp;
  int32_t hor_res;
  int32_t ver_res;
  lv_color_format_t color_format;

  if (result == NULL || result->disp == NULL)
    {
      syslog(LOG_ERR, "[%s] lv_nuttx_init failed for %s: disp=NULL\n",
             APP_LVGLDEMO_TAG, fb_path != NULL ? fb_path : "(null)");
      return;
    }

  disp = result->disp;
  hor_res = lv_display_get_horizontal_resolution(disp);
  ver_res = lv_display_get_vertical_resolution(disp);
  color_format = lv_display_get_color_format(disp);

  syslog(LOG_INFO,
         "[%s] LVGL display ready path=%s disp=%p indev=%p res=%ldx%ld "
         "color_format=%d LV_COLOR_DEPTH=%d\n",
         APP_LVGLDEMO_TAG, fb_path != NULL ? fb_path : "(null)",
         disp, result->indev, (long)hor_res, (long)ver_res,
         (int)color_format, LV_COLOR_DEPTH);
}

static int app_lvgldemo_nuttx_init(const char *fb_path,
                                   lv_nuttx_result_t *result)
{
  lv_nuttx_dsc_t info;

  memset(result, 0, sizeof(*result));
  lv_nuttx_dsc_init(&info);
  info.fb_path = fb_path;

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = CONFIG_APP_LOCAL_LVGLDEMO_INPUT_DEVPATH;
#endif

  syslog(LOG_INFO, "[%s] lv_nuttx_init fb=%s input=%s\n",
         APP_LVGLDEMO_TAG,
         info.fb_path != NULL ? info.fb_path : "(null)",
         info.input_path != NULL ? info.input_path : "(null)");

  lv_nuttx_init(&info, result);
  app_lvgldemo_log_result(info.fb_path, result);

  return result->disp == NULL ? -ENODEV : 0;
}

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
static void lv_nuttx_uv_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
  lv_nuttx_uv_t uv_info;
  void *data;

  uv_loop_init(loop);

  lv_memset(&uv_info, 0, sizeof(uv_info));
  uv_info.loop = loop;
  uv_info.disp = result->disp;
  uv_info.indev = result->indev;
#ifdef CONFIG_UINPUT_TOUCH
  uv_info.uindev = result->utouch_indev;
#endif

#ifdef CONFIG_LV_USE_NUTTX_MOUSE
  uv_info.mouse_indev = result->mouse_indev;
#endif

  data = lv_nuttx_uv_init(&uv_info);
  uv_run(loop, UV_RUN_DEFAULT);
  lv_nuttx_uv_deinit(&data);
}
#endif

