  lv_nuttx_uv_loop(&ui_loop, &result);
#else
  uint32_t loop_count = 0;
  while (1)
    {
      uint32_t idle;
      idle = lv_timer_handler();

      if ((loop_count++ % 1000) == 0)
        {
          syslog(LOG_INFO, "[%s] lv_timer_handler alive idle=%u ms\n",
                 APP_LVGLDEMO_TAG, (unsigned int)idle);
        }

