+
+static int app_lvgldemo_autostart_main(int argc, FAR char *argv[])
+{
+  posix_spawn_file_actions_t actions;
+  posix_spawnattr_t attr;
+  FAR char * const child_argv[] =
+  {
+    APP_LVGLDEMO_AUTOSTART_ARG,
+    NULL
+  };
+
+  pid_t pid;
+  int ret;
+
+  usleep(CONFIG_APP_LOCAL_LVGLDEMO_AUTOSTART_DELAY_MS * 1000);
+
+  ret = posix_spawn_file_actions_init(&actions);
+  if (ret != 0)
+    {
+      syslog(LOG_ERR, "app_lvgldemo autostart actions init failed: %d\n",
+             ret);
+      return ret;
+    }
+
+  ret = posix_spawn_file_actions_addopen(&actions, 0, "/dev/null",
+                                         O_RDONLY, 0);
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addopen(&actions, 1, "/dev/null",
+                                             O_WRONLY, 0);
+    }
+
+  if (ret == 0)
+    {
+      ret = posix_spawn_file_actions_addopen(&actions, 2, "/dev/null",
+                                             O_WRONLY, 0);
+    }
+
+  if (ret != 0)
+    {
+      syslog(LOG_ERR, "app_lvgldemo autostart stdio redirect failed: %d\n",
+             ret);
+      posix_spawn_file_actions_destroy(&actions);
+      return ret;
+    }
+
+  ret = posix_spawnattr_init(&attr);
+  if (ret != 0)
+    {
+      syslog(LOG_ERR, "app_lvgldemo autostart attr init failed: %d\n", ret);
+      posix_spawn_file_actions_destroy(&actions);
+      return ret;
+    }
+
+  posix_spawnattr_setpriority(&attr, CONFIG_APP_LOCAL_LVGLDEMO_PRIORITY);
+  posix_spawnattr_setstacksize(&attr, CONFIG_APP_LOCAL_LVGLDEMO_STACKSIZE);
+
+  pid = task_spawn("app_lvgldemo", app_lvgldemo_main, &actions, &attr,
+                   child_argv, NULL);
+  if (pid < 0)
+    {
+      syslog(LOG_ERR, "app_lvgldemo autostart spawn failed: %d\n", pid);
+    }
+  else
+    {
+      syslog(LOG_INFO, "app_lvgldemo autostart pid=%d\n", pid);
+    }
+
+  posix_spawnattr_destroy(&attr);
+  posix_spawn_file_actions_destroy(&actions);
+
+  return pid < 0 ? -pid : 0;
+}
+
+constructor_fuction static void app_lvgldemo_autostart_init(void)
+{
+  FAR char * const argv[] =
+  {
+    NULL
+  };
+
+  int pid;
+
+  pid = task_create("app_lvgldemo_start",
+                    CONFIG_APP_LOCAL_LVGLDEMO_PRIORITY,
+                    4096,
+                    app_lvgldemo_autostart_main,
+                    argv);
+  if (pid < 0)
+    {
+      syslog(LOG_ERR, "app_lvgldemo autostart task_create failed: %d\n",
+             errno);
+    }
+}
